import math

def check_perfect_power(k):
    """Checks if k is a perfect power (n^c for integers n>1, c>1) and returns the base and exponent if found."""
    if k <= 3:
        return None # 1 is trivial, 2 and 3 are not perfect powers > 1

    # Check for square roots (c=2)
    n_sq = int(round(math.sqrt(k)))
    if n_sq * n_sq == k:
        return (n_sq, 2)

    # Check for cube roots (c=3)
    n_cube = int(round(k**(1/3)))
    if n_cube**3 == k and n_cube > 1:
        return (n_cube, 3)

    # Check for higher powers up to c=6 (since k is small)
    # We only need to check exponents c such that 2^c <= k. Since k=6 or k=8, c max is 3.
    # But let's run a small loop just in case.
    for c in range(4, 7):
        try:
            n_c = int(round(k**(1/c)))
            if n_c > 1 and n_c**c == k:
                return (n_c, c)
        except OverflowError:
            pass
    return None

# Case 1: S=7, k=6
k1 = 6
result1 = check_perfect_power(k1)

# Case 2: S=9, k=8
k2 = 8
result2 = check_perfect_power(k2)

print(f"Analysis of S=7 (k=6): {result1}")
print(f"Analysis of S=9 (k=8): {result2}")

import math
from itertools import product

def is_perfect_power(k, c):
    """Checks if k is a perfect c-th power and returns the base n_S if true."""
    if k <= 0 or c <= 0:
        return None
    try:
        root_float = k**(1/c)
    except OverflowError:
        return None

    n_s = int(round(root_float))

    if abs(math.pow(n_s, c) - k) < 1e-9 and n_s >= 1:
        return n_s
    return None

# Tightened search bounds
MAX_EXPONENT = 3
MAX_BASE = 3

solutions = []

for a in range(1, MAX_EXPONENT + 1):
    for b in range(1, MAX_EXPONENT + 1):
        for c in range(1, MAX_EXPONENT + 1):

            for nB in range(1, MAX_BASE + 1):
                for nT in range(1, MAX_BASE + 1):

                    # Target = nB^a + nT^b + 1
                    K_check = nB**a + nT**b # K_check = n_S^c

                    nS = is_perfect_power(K_check, c)

                    if nS is not None:
                        B = nB**a + 1
                        T = nT**b + 1
                        S = K_check + 1

                        solutions.append({
                            'a': a, 'b': b, 'c': c, 
                            'nB': nB, 'nT': nT, 'nS': nS,
                            'B': B, 'T': T, 'S': S
                        })

total_sum = sum(sol['B'] + sol['T'] + sol['S'] for sol in solutions)

print(f"--- Search Results (A, B, C <= {MAX_EXPONENT}, Bases <= {MAX_BASE}) ---")
print(f"Total number of solutions found: {len(solutions)}")
print(f"Total sum of (B+T+S): {total_sum}")
